import { NotShared, Shared, UsingImmer } from "./1Adding Interactivity/5zCoreCocept"
import Sub from "./subReLearn"
import "./ReLearn.css"
import {useState} from "react"

export default function () {
  const [wow, setWow] = useState(0)
  function Change() {setWow(wow)}
  return (
    <>
    <button onClick={Change}>click</button> <br/>
    {wow}
    </>
  );
}


